html:
{#- Colour and logo come from the site (Security Ops Settings > Badges per
    Company, and the Company record), the same as the gate badges.
    dark = panel and border; the wordmark's second word and the plate
    outline use a lighter tint of it. -#}
{%- set b = get_badge_branding(doc.company) -%}
{%- set dark = b.badge_colour -%}
{%- set accent = "color-mix(in srgb, " ~ dark ~ " 55%, #ffffff)" -%}
{%- set words = (b.company_name or "").lower().split(" ", 1) -%}
{%- set logo = b.logo -%}
<style>
@page { size: 65mm 65mm; margin: 0; }
.sticker-print-slot {
  width: 65mm; height: 65mm; margin: 0 auto; box-sizing: border-box;
  display: flex; flex-direction: column; overflow: hidden;
  font-family: Arial, Helvetica, sans-serif; background: #fff;
  border: 0.8mm solid {{ dark }}; border-radius: 4mm;
}
/* White top band: the company logo, or the name as a two-tone wordmark
   when the Company has no logo set. */
.sticker-brand {
  height: 14mm; flex: none; padding: 0 3mm; box-sizing: border-box; display: flex; align-items: center; justify-content: center;
  font-size: 15pt; letter-spacing: 0.2pt; white-space: nowrap;
}
.sticker-brand img { max-height: 10.5mm; max-width: 100%; object-fit: contain; }
.sticker-brand .w1 { color: {{ dark }}; }
.sticker-brand .w2 { color: {{ accent }}; }
/* Dark lower panel with a thin white rule inset from its edge. */
.sticker-panel {
  flex: 1; background: {{ dark }}; padding: 1.2mm; box-sizing: border-box;
}
.sticker-panel-inner {
  height: 100%; box-sizing: border-box;
  border: 0.35mm solid #fff; border-radius: 2.6mm;
  display: flex; flex-direction: column; align-items: center; justify-content: center;
}
.sticker-title {
  color: #fff; font-family: Georgia, "Times New Roman", serif; font-weight: 700;
  font-size: 11pt; letter-spacing: 0.6pt; margin-bottom: 1.2mm;
}
/* QR on its own white square - full contrast, keeps it scannable. */
.sticker-qr { background: #fff; padding: 1.4mm; line-height: 0; }
.sticker-qr img { width: 27mm; height: 27mm; object-fit: contain; }
.sticker-plate {
  margin-top: 1.4mm; color: #fff; font-size: 8pt; font-weight: 700; letter-spacing: 0.8pt;
  border: 0.3mm solid {{ accent }}; border-radius: 1mm; padding: 0.4mm 2.2mm; white-space: nowrap;
}
</style>

<div class="sticker-print-slot">
  <div class="sticker-brand">
    {%- if logo %}<img src="{{ logo }}" alt="" />
    {%- else %}<span class="w1">{{ words[0] }}</span>{% if words|length > 1 %}<span class="w2">{{ words[1] }}</span>{% endif %}{% endif %}
  </div>
  <div class="sticker-panel">
    <div class="sticker-panel-inner">
      <div class="sticker-title">STAFF CAR PASS</div>
      <div class="sticker-qr"><img src="{{ doc.qr_image }}" alt="" /></div>
      <div class="sticker-plate">{{ doc.plate_number or "—" }}</div>
    </div>
  </div>
</div>

{#- Patrol checkpoint sticker, mounted at the checkpoint: plain black on white,
    half an ID card (85.6 x 54 mm cut across) - 42.5 x 54 mm, portrait. -#}
<style>
@page { size: 42.5mm 54mm; margin: 0; }
.cp-label {
  width: 42.5mm; height: 54mm; margin: 0 auto; box-sizing: border-box;
  display: flex; flex-direction: column; align-items: center; justify-content: center;
  padding: 2mm; overflow: hidden; text-align: center;
  font-family: Arial, Helvetica, sans-serif; color: #000; background: #fff;
  border: 0.4mm solid #000; border-radius: 2mm;
}
.cp-title { font-size: 6pt; font-weight: 700; letter-spacing: 0.6pt; }
.cp-name {
  font-size: 10pt; font-weight: 700; line-height: 1.15; margin-top: 0.8mm;
  max-height: 2.3em; overflow: hidden; word-break: break-word;
}
.cp-qr { line-height: 0; margin-top: 1.2mm; }
.cp-qr img { width: 30mm; height: 30mm; object-fit: contain; }
.cp-code { font-size: 6pt; letter-spacing: 0.5pt; margin-top: 0.6mm; }
</style>

<div class="cp-label">
  <div class="cp-title">PATROL CHECKPOINT</div>
  <div class="cp-name">{{ doc.checkpoint_name or doc.name }}</div>
  <div class="cp-qr"><img src="{{ doc.qr_image }}" alt="" /></div>
  <div class="cp-code">{{ doc.name }}</div>
</div>
